mapper.select:
SELECT target_pool_id AS id , COUNT(DISTINCT security_code) AS current_count FROM ip_pool_status WHERE audit_status = '20' AND is_deleted = 0 AND target_pool_id IN
#{poolId}
GROUP BY target_pool_id

WITH source_company AS ( SELECT company.wind_code AS company_code , MAX(COALESCE(NULLIF(company.full_name, ''), NULLIF(company.short_names, ''))) AS company_name FROM ais_inv_analysis.t_inv_company company WHERE company.wind_code IN
#{companyCode}
AND COALESCE(NULLIF(company.full_name, ''), NULLIF(company.short_names, '')) IS NOT NULL GROUP BY company.wind_code )
, ranked_grade AS ( SELECT grade.windcode , grade.windname , grade.total_score , grade.ts , ROW_NUMBER() OVER ( PARTITION BY grade.windcode ORDER BY grade.ts DESC ) AS row_num FROM ais_inv_analysis.v_inv_grade_result grade WHERE grade.windcode IN
#{companyCode}
)
, ranked_outer_rating AS ( SELECT rating.s_info_compcode , rating.b_info_creditrating , rating.b_info_creditratingagency , ROW_NUMBER() OVER ( PARTITION BY rating.s_info_compcode ORDER BY rating.ann_dt DESC , rating.opdate DESC , rating.object_id DESC ) AS row_num FROM ais_inv_ods.wind_cbondissuerrating rating WHERE EXISTS ( SELECT 1 FROM dict_external_rating_agency agency WHERE agency.is_deleted = 0 AND agency.b_info_creditratingagency = rating.b_info_creditratingagency ) AND EXISTS ( SELECT 1 FROM source_company candidate WHERE candidate.company_code = rating.s_info_compcode ) )
SELECT company.company_code , COALESCE(grade.windname, company.company_name) AS company_name , grade.total_score AS inner_rating , grade.ts AS rating_time , outer_rating.b_info_creditrating AS rating_bondissuer , outer_rating.b_info_creditratingagency AS rating_bondissuer_agency FROM source_company company LEFT JOIN ranked_grade grade ON grade.windcode = company.company_code AND grade.row_num = 1 LEFT JOIN ranked_outer_rating outer_rating ON outer_rating.s_info_compcode = company.company_code AND outer_rating.row_num = 1

WITH requested_security AS ( SELECT wind_code , issuer_code FROM rrs_securityinfo WHERE wind_code IN
#{code}
) SELECT si.wind_code AS security_code , si.issuer_code AS company_code , 0 AS unconfirmed_identity FROM requested_security si WHERE NULLIF(TRIM(si.issuer_code), '') IS NOT NULL UNION ALL SELECT si.wind_code , NULL , 1 FROM requested_security si WHERE NULLIF(TRIM(si.issuer_code), '') IS NULL AND ( EXISTS ( SELECT 1 FROM ip_pool_status ps WHERE ps.security_code = si.wind_code AND ps.audit_status = '20' AND ps.is_deleted = 0 ) OR EXISTS ( SELECT 1 FROM ip_pool_status_crmw ps WHERE ps.security_code = si.wind_code AND ps.audit_status = '20' AND ps.is_deleted = 0 ) ) UNION ALL SELECT log.security_code , snap.issuer_code , NULLIF(TRIM(snap.issuer_code), '') IS NULL FROM ip_adjust_log log LEFT JOIN ip_adjust_security_snapshot snap ON snap.adjust_log_id = log.id AND snap.wind_code = log.security_code AND snap.is_deleted = 0 WHERE log.security_code IN
#{code}
AND log.audit_status IN ('00', '11') AND log.is_deleted = 0 AND (log.pool_type IS NULL OR log.pool_type != 'crmw' OR NULLIF(log.crmw_scode, '') IS NULL) UNION ALL SELECT log.security_code , snap.issuer_code , NULLIF(TRIM(snap.issuer_code), '') IS NULL FROM ip_adjust_log log LEFT JOIN ip_adjust_security_snapshot_crmw snap ON snap.adjust_log_id = log.id AND snap.wind_code = log.security_code AND snap.is_deleted = 0 WHERE log.security_code IN
#{code}
AND log.audit_status IN ('00', '11') AND log.is_deleted = 0 AND log.pool_type = 'crmw' AND NULLIF(log.crmw_scode, '') IS NOT NULL

SELECT DISTINCT current_code.S_INFO_WINDCODE AS security_code , related.S_INFO_WINDCODE AS related_code FROM ais_inv_ods.wind_windcustomcode current_code INNER JOIN ais_inv_ods.wind_windcustomcode related ON related.S_INFO_ISINCODE = current_code.S_INFO_ISINCODE WHERE current_code.S_INFO_WINDCODE IN
#{code}
AND current_code.S_INFO_ISINCODE IS NOT NULL AND TRIM(current_code.S_INFO_ISINCODE) != '' AND current_code.EXCHMARKET IN
#{marketCode}
AND related.EXCHMARKET IN
#{marketCode}
AND NOT EXISTS ( SELECT 1 FROM rrs_securityinfo si WHERE si.wind_code = current_code.S_INFO_WINDCODE AND si.security_source = 'temporary' ) AND related.S_INFO_WINDCODE != current_code.S_INFO_WINDCODE AND related.S_INFO_WINDCODE IS NOT NULL AND TRIM(related.S_INFO_WINDCODE) != '' ORDER BY security_code, related_code

SELECT ips.security_code , ips.target_pool_id AS pool_id , ips.security_type , CASE WHEN al.id IS NOT NULL THEN COALESCE(ips.entry_time, al.audit_time, ips.crte_time) END AS entry_time FROM ip_pool_status ips LEFT JOIN ip_adjust_log al ON al.id = ips.adjust_log_id WHERE ips.audit_status = '20' AND ips.is_deleted = 0 AND ips.security_code IN
#{code}
ORDER BY ips.id

SELECT DISTINCT manual_log.security_code , occupied.target_pool_id AS pool_id FROM ip_adjust_log manual_log INNER JOIN ip_adjust_step pending_step ON pending_step.adjust_batch_no = manual_log.adjust_batch_no AND pending_step.step_status = 'pending' INNER JOIN ip_adjust_log occupied ON occupied.adjust_batch_no = manual_log.adjust_batch_no AND occupied.audit_status IN ('00', '11') AND occupied.is_deleted = 0 WHERE manual_log.security_code IN
#{code}
AND manual_log.adjust_type IN ('手工调整', '手动批量调整') AND manual_log.audit_status IN ('00', '11') AND manual_log.is_deleted = 0

SELECT ranked.security_code , ranked.node_label FROM ( SELECT al.security_code , s.node_label , ROW_NUMBER() OVER (PARTITION BY al.security_code ORDER BY s.sort_order, s.id, al.submit_time DESC, al.id DESC) AS seq FROM ip_adjust_log al INNER JOIN ip_adjust_step s ON s.adjust_batch_no = al.adjust_batch_no WHERE al.is_deleted = 0 AND s.step_status = 'pending' AND al.security_code IN
#{code}
) ranked WHERE ranked.seq = 1

SELECT DISTINCT pool_id
FROM ip_pool_open_day
WHERE is_deleted = 0
  AND begin_date <= #{today}
  AND end_date >= #{today}
  AND pool_id IN

    #{code}

SELECT DISTINCT r.s_info_compcode FROM ais_inv_ods.wind_cbondissuerrating r WHERE r.s_info_compcode IN
#{code}
AND r.b_info_creditratingagency IN
#{agencyCode}
AND 1 = 0
AND r.ann_dt >= DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 1 YEAR), '%Y%m%d') AND REGEXP_SUBSTR(TRIM(r.b_info_creditrating), '^(A+|B+|C+|D)[+-]?', 1, 1, 'c') IN ( 'AA-', 'A+', 'A', 'A-' ,'BBB+', 'BBB', 'BBB-' ,'BB+', 'BB', 'BB-' ,'B+', 'B', 'B-' ,'CCC', 'CC', 'C', 'D' )

SELECT ranked.company_code , ranked.credit_rating , ranked.pre_credit_rating , ranked.credit_rating_change FROM ( SELECT r.s_info_compcode AS company_code , r.b_info_creditrating AS credit_rating , r.b_info_precreditrating AS pre_credit_rating , r.b_creditratingchange AS credit_rating_change , ROW_NUMBER() OVER (PARTITION BY r.s_info_compcode ORDER BY r.ann_dt DESC) AS seq FROM ais_inv_ods.wind_cbondissuerrating r WHERE r.s_info_compcode IN
#{code}
AND r.b_info_creditratingagency IN
#{code}
) ranked WHERE ranked.seq = 1

SELECT DISTINCT si.issuer_code FROM ip_pool_status ips INNER JOIN rrs_securityinfo si ON si.wind_code = ips.security_code INNER JOIN dict_security_type dst ON dst.security_type = ips.security_type AND dst.category_type = 'bond' AND dst.is_deleted = 0 WHERE si.issuer_code IN
#{code}
AND si.issuer_code IS NOT NULL AND si.issuer_code != '' AND ips.pool_type = 'credit_bond' AND ips.adjust_mode = '调入' AND ips.flow_type IS NOT NULL AND ips.flow_type != '' AND ips.flow_type != 'simpleInbound' AND ips.audit_status = '20' AND ips.entry_time >= DATE_SUB(NOW(), INTERVAL #{days} DAY) AND ips.entry_time <= NOW()

SELECT DISTINCT si.issuer_code FROM ip_pool_status ips INNER JOIN ip_adjust_log l ON l.id = ips.adjust_log_id AND l.security_code = ips.security_code INNER JOIN rrs_securityinfo si ON si.wind_code = ips.security_code INNER JOIN dict_security_type dst ON dst.security_type = ips.security_type AND dst.category_type = 'bond' AND dst.is_deleted = 0 WHERE si.issuer_code IN
#{code}
AND si.issuer_code IS NOT NULL AND si.issuer_code != '' AND ips.adjust_mode = '调入' AND ips.audit_status = '20' AND ips.entry_time >= DATE_SUB(NOW(), INTERVAL #{days} DAY) AND ips.entry_time <= NOW() AND l.adjust_mode = '调入' AND l.audit_status = '20' AND l.is_deleted = 0 AND EXISTS ( SELECT 1 FROM sys_attachment a WHERE a.table_name = 'ip_adjust_log' AND a.main_id = l.id AND a.attachment_category IN ('credit_report_hand', 'credit_report_in', 'credit_report_out') AND a.is_deleted = 0 )

SELECT DISTINCT si.issuer_code FROM ip_adjust_log l INNER JOIN rrs_securityinfo si ON si.wind_code = l.security_code WHERE l.audit_status = '20' AND l.adjust_mode = '调入' AND l.is_deleted = 0 AND l.crte_time >= DATE_SUB(NOW(), INTERVAL 6 MONTH) AND si.issuer_code IN
#{code}
AND EXISTS ( SELECT 1 FROM sys_attachment a WHERE a.table_name = 'ip_adjust_log' AND a.main_id = l.id AND a.is_deleted = 0 AND a.attachment_category IN ('credit_report_hand', 'credit_report_in', 'credit_report_out') )
